def fill_between_2s_rule(grid, min_gap):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    result = [row[:] for row in grid]

    # Check if cell is "inside" a 2-shape (same row as a 2, adjacent to 2s)
    # If so, don't fill it (unless we're inside a gap)

    # Horizontal fill
    for r in range(rows):
        two_cols = sorted([c for c in range(cols) if grid[r][c] == 2])
        for i in range(len(two_cols) - 1):
            start = two_cols[i]
            end = two_cols[i + 1]
            gap = end - start - 1
            if gap >= min_gap:
                for c in range(start + 1, end):
                    if grid[r][c] == 0:
                        result[r][c] = 1

    # Vertical fill
    for c in range(cols):
        two_rows = sorted([r for r in range(rows) if grid[r][c] == 2])
        for i in range(len(two_rows) - 1):
            start = two_rows[i]
            end = two_rows[i + 1]
            gap = end - start - 1
            if gap >= min_gap:
                for r in range(start + 1, end):
                    if grid[r][c] == 0:
                        result[r][c] = 1

    return result

