def fill_with_gap_constraint(grid, max_gap=1):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    result = [row[:] for row in grid]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0:
                two_cols = sorted([cc for cc in range(cols) if grid[r][cc] == 2])
                horizontal_between = False
                for i in range(len(two_cols)-1):
                    if two_cols[i] < c < two_cols[i+1]:
                        gap = two_cols[i+1] - two_cols[i] - 1
                        if gap <= max_gap:
                            horizontal_between = True

                two_rows = sorted([rr for rr in range(rows) if grid[rr][c] == 2])
                vertical_between = False
                for i in range(len(two_rows)-1):
                    if two_rows[i] < r < two_rows[i+1]:
                        gap = two_rows[i+1] - two_rows[i] - 1
                        if gap <= max_gap:
                            vertical_between = True

                if horizontal_between != vertical_between:
                    result[r][c] = 1

    return result

