def fill_longest_gap_only(grid):
    rows = len(grid)
    cols = len(grid[0])
    result = [row[:] for row in grid]

    # Find max gap in each row
    max_h_gap = -1
    for r in range(rows):
        two_cols = sorted([c for c in range(cols) if grid[r][c] == 2])
        if len(two_cols) > 1:
            row_max_gap = max(two_cols[i+1] - two_cols[i] - 1 for i in range(len(two_cols)-1))
            if row_max_gap > max_h_gap:
                max_h_gap = row_max_gap

    # Find max gap in each col
    max_v_gap = -1
    for c in range(cols):
        two_rows = sorted([r for r in range(rows) if grid[r][c] == 2])
        if len(two_rows) > 1:
            col_max_gap = max(two_rows[i+1] - two_rows[i] - 1 for i in range(len(two_rows)-1))
            if col_max_gap > max_v_gap:
                max_v_gap = col_max_gap

    # Fill: only the longest gap
    if max_h_gap >= max_v_gap:
        # Fill horizontal
        for r in range(rows):
            two_cols = sorted([c for c in range(cols) if grid[r][c] == 2])
            if len(two_cols) > 1:
                row_max_gap = max(two_cols[i+1] - two_cols[i] - 1 for i in range(len(two_cols)-1))
                if row_max_gap == max_h_gap:
                    for i in range(len(two_cols) - 1):
                        start = two_cols[i]
                        end = two_cols[i+1]
                        gap_len = end - start - 1
                        if gap_len == max_h_gap:
                            for c in range(start+1, end):
                                if grid[r][c] == 0:
                                    result[r][c] = 1
    else:
        # Fill vertical (only in rows without 2s)
        for c in range(cols):
            two_rows = sorted([r for r in range(rows) if grid[r][c] == 2])
            if len(two_rows) > 1:
                col_max_gap = max(two_rows[i+1] - two_rows[i] - 1 for i in range(len(two_rows)-1))
                if col_max_gap == max_v_gap:
                    for i in range(len(two_rows) - 1):
                        start = two_rows[i]
                        end = two_rows[i+1]
                        gap_len = end - start - 1
                        if gap_len == max_v_gap:
                            for r in range(start+1, end):
                                if grid[r].count(2) == 0 and grid[r][c] == 0:
                                    result[r][c] = 1

    return result

